<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import { listChats,chatMessages,deleteChat,restoreChat,exportChat,type ChatItem,type Message } from '@/api/operations'
const auth=useAuthStore(), query=reactive({userId:'',expertId:'',keyword:'',start:'',end:'',deleted:'',page:1,pageSize:20}), items=ref<ChatItem[]>([]),total=ref(0),loading=ref(false),visible=ref(false),messages=ref<Message[]>([]),selected=ref<number>()
async function load(){loading.value=true;try{const data=await listChats(query);if(!data.list.length&&query.page>1){query.page--;await load();return}items.value=data.list;total.value=data.total}finally{loading.value=false}}
async function search(){query.page=1;await load()}
const detailLoading=ref(false);async function detail(row:ChatItem){selected.value=row.id;messages.value=[];visible.value=true;detailLoading.value=true;try{messages.value=await chatMessages(row.id)}finally{detailLoading.value=false}}
async function remove(row:ChatItem){try{const {value}=await ElMessageBox.prompt('请填写软删除理由，消息会保留以便恢复','软删除',{inputValidator:v=>!!v?.trim() || '必须填写理由'});await deleteChat(row.id,value);await load()}catch(e){if(e!=='cancel'&&e!=='close')throw e}}
async function restore(row:ChatItem){try{await ElMessageBox.confirm(`恢复会话 ${row.id}？恢复后用户可继续该会话`,'确认恢复')}catch{return}await restoreChat(row.id);await load()}
async function download(row:ChatItem,format:string){const data=await exportChat(row.id,format);const blob=data instanceof Blob?data:new Blob([data.content],{type:format==='json'?'application/json':'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=data instanceof Blob?`chat-${row.id}.${format}`:data.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
onMounted(load)
</script>
<template><el-alert title="对话为敏感数据；摘要与消息默认脱敏，每次打开消息及导出均留审计。" type="warning" :closable="false" style="margin-bottom:16px"/><el-card shadow="never"><el-form inline @submit.prevent="search"><el-form-item label="用户ID"><el-input v-model="query.userId" style="width:100px"/></el-form-item><el-form-item label="专家ID"><el-input v-model="query.expertId" style="width:100px"/></el-form-item><el-form-item><el-input v-model="query.keyword" placeholder="消息关键词" clearable/></el-form-item><el-form-item><el-date-picker v-model="query.start" value-format="YYYY-MM-DD" placeholder="开始日期" style="width:145px"/></el-form-item><el-form-item><el-date-picker v-model="query.end" value-format="YYYY-MM-DD" placeholder="结束日期" style="width:145px"/></el-form-item><el-form-item><el-select v-model="query.deleted" style="width:130px"><el-option label="正常会话" value=""/><el-option label="已软删除" value="true"/><el-option label="全部" value="all"/></el-select></el-form-item><el-button type="primary" @click="search">查询</el-button></el-form><el-table v-loading="loading" :data="items"><el-table-column prop="id" label="ID" width="65"/><el-table-column prop="userId" label="用户ID" width="85"/><el-table-column prop="expertName" label="专家" min-width="130"/><el-table-column prop="summary" label="脱敏摘要" min-width="240"/><el-table-column prop="createdAt" label="时间" min-width="170"/><el-table-column label="状态" min-width="130"><template #default="{row}">{{row.deletedAt?'已删除':'正常'}}<small v-if="row.deletedAt"><br/>{{row.deleteReason}}</small></template></el-table-column><el-table-column label="操作" min-width="215" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detail(row)">消息详情</el-button><el-button v-if="!row.deletedAt && auth.hasPerm('chat:delete')" link type="danger" @click="remove(row)">软删除</el-button><el-button v-if="row.deletedAt && auth.hasPerm('chat:restore')" link @click="restore(row)">恢复</el-button><el-dropdown v-if="auth.hasPerm('chat:export')" @command="(cmd: string | number | object) => download(row, String(cmd))"><el-button link type="primary">导出 ▾</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="json">JSON</el-dropdown-item><el-dropdown-item command="csv">CSV</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="search" style="margin-top:20px"/></el-card><el-drawer v-model="visible" :title="`会话 ${selected} · 已记录查看审计`" size="650px"><div v-loading="detailLoading" style="min-height:120px"><article v-for="(m,i) in messages" :key="i" style="padding:20px;border-bottom:1px solid #eee"><strong>{{m.role}}</strong><small> · {{m.createdAt}}</small><p style="white-space:pre-wrap">{{m.content}}</p></article><el-empty v-if="!detailLoading && !messages.length" description="无消息记录" /></div></el-drawer></template>
